INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('a2eac8fd-2636-443b-8110-3600a22409c8', 'f4ad6589-72fe-48ac-84c0-7b750cbd1231', '{28398815-1483-4338-9cae-1e5b5fe27d91}'::uuid[], 'Deez One Mod', NULL, NULL, '{Harmonic Coloration}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], 'The Keeley DS-1 Mod (specifically the "Ultra Mod" or "Seeing Eye Mod") is a popular, early-2000s modification for the Boss DS-1 distortion pedal, replacing stock components with high-quality, low-noise parts (metal film/poly capacitors).  It typically includes a toggle switch for two modes: a "Seeing Eye" mode (LED flashes with playing intensity) and an "Ultra" mode for a thicker, more Marshall-like, compressed gain.', 'Boss DS-1 TOP (Keeley Mod)', NULL, 'eliminates harsh, fizzy top-end frequencies while adding significant bass and midrange.', NULL, NULL::jsonb, '{Guitar,Modeled,Stomp}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('4ee233fa-d300-4cab-a30b-59d16abb9c49', 'f4ad6589-72fe-48ac-84c0-7b750cbd1231', '{60d3dc7d-a12b-4dec-8fc7-4c9201fe4540}'::uuid[], '80A Flanger', NULL, 'Legacy', '{Modulation}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'A/DA Flanger ALT (Tone)', NULL, 'Gritty and spacey sweeps inspired by the distinctive sound of the A/DA Flanger. More experimental (metallic clanging and slow warble rather than the classic sweep)', NULL, NULL::jsonb, '{Guitar,Modeled,Stomp}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
