INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('740be1e1-0764-4bef-a528-f6d8c3ae8dd2', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{d6888014-2edc-4157-8d80-63731103cce7}'::uuid[], '4x10 S-Verb', NULL, NULL, '{Combo}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], '(1966) 4x10 CAB Fender CTS', 'Fender ''65 Super Reverb (CAB) ALT (Tone)', NULL, 'Plenty of midrange, great for surf sounds, almost lo-fi. mic''d w/ an AKG C414', NULL, NULL::jsonb, '{Guitar,Modeled}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('7efca2c1-656f-457c-81ed-d726530c4d8b', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{887ddb64-0dbe-4b14-83d4-d317c3a30b21}'::uuid[], '10-Band Graphic EQ', NULL, NULL, '{EQ}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'MXR Ten Band EQ ALT (Tone)', NULL, 'Precise control of 10 EQ bands for your sound. Use for tone shaping or emphasizing certain frequencies to drive an amp harder.Use to shape your sound before or after a distortion pedal. For example, you can boost low frequencies after the Raw Distortion pedal (which reduces bass at low gain settings), or cut some mid frequencies from the Gold Overdrive (which can be mid-heavy).
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('cc603f90-b5ff-4426-9195-9b64cb791c04', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{71bd4004-3ac7-452f-a625-81d487427b7b}'::uuid[], 'Digital Delay', NULL, NULL, '{Delay}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'TC Electronic 2290 TOP', NULL, 'Pristine, mirror-image repeats with dynamic, shimmering modulation effects. Lots of options to filter, sync, and tweak your echoes. Enable Sync to add dual time offsets like 1/4 + 1/8 in stereo. Use the low and high cut filters for creative delay washes. For example, create a dark atmosphere by setting Low Cut to minimum and High Cut in the 300-400 Hz range.   
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('9e321f3c-d295-4488-8d79-9e536f5704bc', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{eff16a4b-4b2d-40a2-bb48-a14ba684da87}'::uuid[], 'Nashville Overdrive', NULL, NULL, '{Harmonic Coloration}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'Nobels ODR-1(bc) ALT (Tone)', NULL, 'Prized for warm, transparent tube-like distortion, this Nashville favorite is often paired with Dream- and Showtime-style amps to enhance their natural compression and drive. The original Nashville OD can have more bass than you need, but we put it on a knob so you can dial it down. Bass has the stock sound when set to 10. The Spectrum control is unusual. Below noon, treble and bass are reduced, for a very mid-forward sound. At high settings, the sound gets scooped with extra bass and treble. Use high spectrum settings to brighten the Ruby normal channel, and lower settings to de-emphasize the scooped sound of Dream. 
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('f0c2bfcb-715a-4b8c-b782-8e0ea7bed27d', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', NULL::uuid[], 'Fire', NULL, 'Verve Analog Machines (Full)', '{Harmonic Coloration}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], 'Tape Machine w/ Warble', NULL, NULL, 'Push a studio tape machine far past its limits and hear it roar.', NULL, NULL::jsonb, NULL::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
