INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('ae05adaf-33dd-4ae4-b2eb-d1accba49517', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{f9691b9c-6294-4e8e-88b1-a40dad5aef60}'::uuid[], 'Big Fuzz', NULL, NULL, '{Harmonic Coloration}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'Electro-Harmonix Big Muff Pi TOP', NULL, 'Super Saturated w/ huge low end and massive sustain. Thick heavy and loose. Bypass tone knob for even more gain + mids. The tone control on these pedals is an unusual "tilt" design that increases highs while reducing lows,and vice-versa. This can yield massive tonal changes with small moves. Set low for extremely dark "in a cave" tones, or high for AM radio-type effects. 
