INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('574d93f9-8eae-4259-a1af-c702bfaea6a4', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{8a4fb42d-c8d7-4755-8be0-da9ebafdccbb}'::uuid[], 'Red Comp', NULL, NULL, '{Dynamics}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, 'MXR Dyna Comp TOP', NULL, 'The signal is somewhat clipped when pushed, with plenty of over-the-top squish. Not the most subtle compressor, so blend it with the custom Mix knob. For classic picking, set the sensitivity high (2 to 4 o''clock), and adjust Output to match unity level. Great for fast picking runs with an edgy bite when you dig in. 
