INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('a798a475-e3a1-4033-80c2-602daadcd918', 'f772e5f8-1e3c-11f1-a0d3-0072ee78ad39', '{d7aa9733-5fa2-4cfd-b1ac-a6984b2e9dd5}'::uuid[], 'Pitch Shift Delay', NULL, NULL, '{Delay,Modulation}'::effect_type[], NULL::tool_type[], NULL::plugin_format[], 'modded', 'Chase Bliss Thermae TOP', NULL, 'Use at very low mix settings for wildly distorted background sound design-style beds.', NULL, NULL::jsonb, '{Guitar,Modeled,Stomp}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
