INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('459e4eac-54e7-4cc8-9bdd-792b78c0b9cb', '52ca057c-1c70-4093-81ad-720a2ba3ac60', NULL::uuid[], 'Silverado', NULL, NULL, NULL::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, NULL, NULL, 'Era: ’60s to current day. Fat, punchy, and clear. A versatile amp that’s between mild and aggressive amps. • Clean ranges from pristine clean to mild crunch. • Drive is touch sensitive, with mild overdrive when played harder. • Lead is big, fuzzy, lost of low end. Classic ’70s hero guitar sound.', NULL, NULL::jsonb, '{Guitar}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('ce3d8fab-1485-40f4-8646-7ea04b0f0bd2', '52ca057c-1c70-4093-81ad-720a2ba3ac60', NULL::uuid[], 'Blue Flame', NULL, NULL, NULL::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, NULL, NULL, 'Era: ’80s to current day. Can range from pristine clean to mild crunch. • Clean channel ranges from fat/clean to pleasing overdrive. • Drive channel is tight, aggressive, but not so percussive. • Lead is horn-like, with a nice top end, lots of gain, with a singing lead tone.', NULL, NULL::jsonb, '{Guitar}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('01f5218c-fc07-4122-8078-3f925f951b18', '52ca057c-1c70-4093-81ad-720a2ba3ac60', NULL::uuid[], 'Arena', NULL, NULL, NULL::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, NULL, NULL, 'Era: Late ’70s to current day. Hot rodded British sound. • Clean channel has a mild crunch with a fair amount of gain. • Drive is articulate, thick with top-end bite. • Lead is open sounding with lots of gain.', NULL, NULL::jsonb, '{Guitar}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('b75b8752-eead-42c5-87d6-ecc605178231', '52ca057c-1c70-4093-81ad-720a2ba3ac60', NULL::uuid[], 'Aggro', NULL, NULL, NULL::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, NULL, NULL, 'Era: Late ’90s to current day guitar tones. This is an aggressive amp for aggressive music. • Clean channel runs from very clean to mid-crunchy tones. • Drive responds very quickly and is very responsive. • Lead is smooth and less percussive.', NULL, NULL::jsonb, '{Guitar}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
INSERT INTO effects (effect_id, brand_id, model_ids, effect_name, version, collection, effect_types, tool_types, plugin_formats, plugin_notes, workflow_notes, description, recording_notes, artist_reference, attributes, tags) VALUES ('733a0ccb-57c1-4697-99be-448c4600b65f', '52ca057c-1c70-4093-81ad-720a2ba3ac60', NULL::uuid[], 'Royal-X', NULL, NULL, NULL::effect_type[], NULL::tool_type[], NULL::plugin_format[], NULL, NULL, NULL, 'Era: Late ’90s to modern-day guitar sounds with sparkling tones and punch. • Clean channel is fat and chime-like. • Drive channel has added breakup-style gain. • Lead channel retains chime, while adding lots of gain.', NULL, NULL::jsonb, '{Guitar}'::tag_type[]) ON CONFLICT (effect_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, effect_name = EXCLUDED.effect_name, version = EXCLUDED.version, collection = EXCLUDED.collection, effect_types = EXCLUDED.effect_types, tool_types = EXCLUDED.tool_types, plugin_formats = EXCLUDED.plugin_formats, plugin_notes = EXCLUDED.plugin_notes, workflow_notes = EXCLUDED.workflow_notes, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, tags = EXCLUDED.tags, updated_at = NOW();
